const SLASH = {
  t: (date) => date.toTimeString().slice(0, 5)
};

function timeStamp(text, date) {
  const word = text.match(/(?:^|\s)\/(\w+) $/);
  if (!word || !SLASH[word[1]]) return text;
  const start = text.length - word[1].length - 2;   // where the / is
  return text.slice(0, start) + SLASH[word[1]](date) + " ";
}

console.log(timeStamp("meeting /t ", new Date(2026, 10, 27, 14, 5)));
console.log(timeStamp("/t ", new Date(2026, 10, 27, 9, 30)));
console.log(timeStamp("a/t ", new Date()));

